OLD_RUNTIME_GUARD = "CREATE OR REPLACE FUNCTION guard_runtime_run() RETURNS trigger LANGUAGE plpgsql AS $$\n    BEGIN\n        IF TG_OP IN ('UPDATE','DELETE') AND OLD.status <> 'running' THEN\n            RAISE EXCEPTION 'Final run records are immutable' USING ERRCODE = '23514';\n        END IF;\n        IF TG_OP = 'DELETE' THEN\n            RAISE EXCEPTION 'Run history cannot be deleted' USING ERRCODE = '23514';\n        END IF;\n        IF TG_OP = 'UPDATE' AND ROW(NEW.id, NEW.agent_id, NEW.version_number,\n          NEW.caller_id, NEW.model_id, NEW.config_hash, NEW.workflow_version,\n          NEW.mode, NEW.started_at)\n          IS DISTINCT FROM ROW(OLD.id, OLD.agent_id, OLD.version_number,\n          OLD.caller_id, OLD.model_id, OLD.config_hash, OLD.workflow_version,\n          OLD.mode, OLD.started_at) THEN\n            RAISE EXCEPTION 'Immutable run identity' USING ERRCODE = '23514';\n        END IF;\n        IF TG_OP = 'INSERT' AND (NEW.status <> 'running' OR NOT EXISTS (\n            SELECT 1 FROM agent_versions v JOIN agent_invocations g\n              ON g.agent_id = v.agent_id AND g.version_number = v.number\n            WHERE v.agent_id = NEW.agent_id AND v.number = NEW.version_number\n              AND v.status = 'snapshot' AND v.model_id = NEW.model_id\n              AND v.config_hash = NEW.config_hash AND g.user_id = NEW.caller_id AND g.enabled\n        )) THEN\n            RAISE EXCEPTION 'Run requires the exact authorized snapshot'\n                USING ERRCODE = '23514';\n        END IF;\n        RETURN NEW;\n    END $$"


