GOVERNANCE_GUARDS = """
CREATE FUNCTION guard_evaluation_run() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE n integer; p integer; c integer;
BEGIN
  IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND OLD.status <> 'running') THEN
    RAISE EXCEPTION 'Evaluation history is immutable' USING ERRCODE='23514';
  END IF;
  IF TG_OP = 'UPDATE' AND (to_jsonb(NEW) - ARRAY['status','passed_count','critical_failures','completed_at'])
    IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status','passed_count','critical_failures','completed_at']) THEN
    RAISE EXCEPTION 'Immutable evaluation identity' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM agent_versions v JOIN evaluation_suites s
    ON s.id=NEW.suite_id AND s.version=NEW.suite_version
    WHERE v.agent_id=NEW.agent_id AND v.number=NEW.version_number AND v.status='snapshot'
      AND v.config_hash=NEW.config_hash AND s.suite_hash=NEW.suite_hash
      AND jsonb_array_length(s.checks)=NEW.total) THEN
    RAISE EXCEPTION 'Evaluation requires exact version and suite hashes' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' AND (NEW.status<>'running' OR NEW.passed_count<>0 OR NEW.critical_failures<>0) THEN
    RAISE EXCEPTION 'Evaluation must start running' USING ERRCODE='23514';
  END IF;
  IF NEW.status<>'running' THEN
    SELECT count(*), count(*) FILTER(WHERE passed), count(*) FILTER(WHERE critical AND NOT passed)
      INTO n,p,c FROM evaluation_results WHERE evaluation_id=NEW.id;
    IF n<>NEW.total OR p<>NEW.passed_count OR c<>NEW.critical_failures
      OR (NEW.status='passed' AND p<>n) THEN
      RAISE EXCEPTION 'Evaluation summary must match immutable results' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION guard_evaluation_result() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM evaluation_runs e JOIN evaluation_suites s
    ON s.id=e.suite_id AND s.version=e.suite_version WHERE e.id=NEW.evaluation_id
    AND e.status='running' AND s.checks ? NEW.check) THEN
    RAISE EXCEPTION 'Result must belong to the running suite' USING ERRCODE='23514';
  END IF;
  IF NEW.critical IS DISTINCT FROM (NEW.check IN ('configuration','invoice','comparison','knowledge',
      'cross_customer','prompt_injection','missing_invoice','tool_permission')) THEN
    RAISE EXCEPTION 'Criticality is server policy' USING ERRCODE='23514';
  END IF;
  IF NEW.run_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM agent_runs
    WHERE id=NEW.run_id AND evaluation_id=NEW.evaluation_id AND status<>'running') THEN
    RAISE EXCEPTION 'Evidence must be a terminal run from this evaluation' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION guard_approval() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND OLD.status<>'pending') THEN
    RAISE EXCEPTION 'Decided approvals are immutable' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['status','decided_by','decided_at','reason'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','decided_by','decided_at','reason']) THEN
    RAISE EXCEPTION 'Immutable approval identity' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' AND NEW.status<>'pending' THEN
    RAISE EXCEPTION 'Approval must start pending' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM evaluation_runs e JOIN agent_versions v
    ON v.agent_id=e.agent_id AND v.number=e.version_number
    WHERE e.id=NEW.evaluation_id AND e.agent_id=NEW.agent_id AND e.version_number=NEW.version_number
    AND e.config_hash=NEW.config_hash AND v.config_hash=NEW.config_hash
    AND e.status='passed' AND e.critical_failures=0) THEN
    RAISE EXCEPTION 'Approval requires passing evaluation of the exact hash' USING ERRCODE='23514';
  END IF;
  IF NEW.status<>'pending' AND NOT EXISTS(SELECT 1 FROM users u JOIN agents a ON a.id=NEW.agent_id
    JOIN agent_versions v ON v.agent_id=a.id AND v.number=NEW.version_number
    WHERE u.id=NEW.decided_by AND u.active AND u.role IN ('approver','administrator')
    AND u.id<>NEW.requested_by AND u.id<>a.owner_id AND u.id<>v.created_by) THEN
    RAISE EXCEPTION 'Authorized independent approver required' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION guard_governance_state() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'Lifecycle history cannot be deleted' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM agent_versions WHERE agent_id=NEW.agent_id
    AND number=NEW.version_number AND status='snapshot' AND config_hash=NEW.config_hash) THEN
    RAISE EXCEPTION 'Governance requires an exact frozen version' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' AND (NEW.stage<>'draft' OR NEW.ever_published) THEN
    RAISE EXCEPTION 'Lifecycle must begin as draft' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' THEN
    IF ROW(NEW.agent_id,NEW.version_number,NEW.config_hash) IS DISTINCT FROM
      ROW(OLD.agent_id,OLD.version_number,OLD.config_hash) OR NEW.revision<>OLD.revision+1
      OR (OLD.ever_published AND NOT NEW.ever_published) THEN
      RAISE EXCEPTION 'Immutable governance identity or stale revision' USING ERRCODE='23514';
    END IF;
    IF NOT ((OLD.stage IN ('draft','testing','pending_approval','approved') AND NEW.stage='testing' AND NOT OLD.ever_published)
      OR (OLD.stage='testing' AND NEW.stage='pending_approval')
      OR (OLD.stage='pending_approval' AND NEW.stage IN ('approved','draft'))
      OR (OLD.stage='approved' AND NEW.stage='published')
      OR (OLD.stage IN ('deprecated','disabled') AND OLD.ever_published AND NEW.stage='published')
      OR (OLD.stage='published' AND NEW.stage IN ('deprecated','disabled'))
      OR (OLD.stage IN ('approved','deprecated') AND NEW.stage='disabled')) THEN
      RAISE EXCEPTION 'Invalid lifecycle transition' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.stage IN ('pending_approval','approved','published') AND NOT EXISTS(
    SELECT 1 FROM evaluation_runs e JOIN evaluation_suites s ON s.id=e.suite_id AND s.version=e.suite_version
    WHERE e.id=NEW.latest_evaluation_id AND e.agent_id=NEW.agent_id AND e.version_number=NEW.version_number
      AND e.config_hash=NEW.config_hash AND e.status='passed' AND e.passed_count=e.total
      AND e.critical_failures=0 AND e.runner_version='billing-evaluator-v1'
      AND s.suite_hash=e.suite_hash AND s.checks @> '["configuration","invoice","comparison","knowledge","cross_customer","prompt_injection","missing_invoice","tool_permission"]'::jsonb
  ) THEN
    RAISE EXCEPTION 'Publication gate requires all mandatory checks for exact hash' USING ERRCODE='23514';
  END IF;
  IF NEW.stage IN ('pending_approval','approved','published') AND NOT EXISTS(SELECT 1 FROM approvals
    WHERE id=NEW.approval_id AND agent_id=NEW.agent_id AND version_number=NEW.version_number
    AND config_hash=NEW.config_hash AND evaluation_id=NEW.latest_evaluation_id
    AND (NEW.stage='pending_approval' AND status='pending' OR NEW.stage<>'pending_approval' AND status='approved')) THEN
    RAISE EXCEPTION 'Lifecycle requires matching approval' USING ERRCODE='23514';
  END IF;
  IF NEW.stage='published' AND NOT NEW.ever_published THEN
    RAISE EXCEPTION 'Publication history flag required' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION check_active_publication() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE aid text; v integer; active boolean;
BEGIN
  aid := NEW.agent_id;
  SELECT version_number,enabled INTO v,active FROM agent_publications WHERE agent_id=aid;
  IF active AND NOT EXISTS(SELECT 1 FROM version_governance
      WHERE agent_id=aid AND version_number=v AND stage='published' AND ever_published) THEN
    RAISE EXCEPTION 'Active pointer requires a published approved lifecycle' USING ERRCODE='23514';
  END IF;
  IF EXISTS(SELECT 1 FROM version_governance g WHERE g.agent_id=aid AND g.stage='published'
      AND NOT EXISTS(SELECT 1 FROM agent_publications p WHERE p.agent_id=aid
        AND p.enabled AND p.version_number=g.version_number)) THEN
    RAISE EXCEPTION 'Published version must be the sole active pointer' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;

CREATE FUNCTION guard_publication_actor() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'Publication history cannot be deleted' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.updated_by AND active AND role IN ('administrator','approver')) THEN
    RAISE EXCEPTION 'Publication requires an authorized actor' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND (NEW.agent_id<>OLD.agent_id OR NEW.revision<>OLD.revision+1) THEN
    RAISE EXCEPTION 'Stale publication revision' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER immutable_suite BEFORE UPDATE OR DELETE ON evaluation_suites
  FOR EACH ROW EXECUTE FUNCTION immutable_runtime_trace();
CREATE TRIGGER guard_evaluation BEFORE INSERT OR UPDATE OR DELETE ON evaluation_runs
  FOR EACH ROW EXECUTE FUNCTION guard_evaluation_run();
CREATE TRIGGER guard_result BEFORE INSERT ON evaluation_results
  FOR EACH ROW EXECUTE FUNCTION guard_evaluation_result();
CREATE TRIGGER immutable_result BEFORE UPDATE OR DELETE ON evaluation_results
  FOR EACH ROW EXECUTE FUNCTION immutable_runtime_trace();
CREATE TRIGGER guard_decision BEFORE INSERT OR UPDATE OR DELETE ON approvals
  FOR EACH ROW EXECUTE FUNCTION guard_approval();
CREATE TRIGGER guard_lifecycle BEFORE INSERT OR UPDATE OR DELETE ON version_governance
  FOR EACH ROW EXECUTE FUNCTION guard_governance_state();
CREATE TRIGGER guard_publication BEFORE INSERT OR UPDATE OR DELETE ON agent_publications
  FOR EACH ROW EXECUTE FUNCTION guard_publication_actor();
CREATE CONSTRAINT TRIGGER consistent_publication AFTER INSERT OR UPDATE ON agent_publications
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_active_publication();
CREATE CONSTRAINT TRIGGER consistent_lifecycle AFTER INSERT OR UPDATE ON version_governance
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_active_publication();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events
  FOR EACH ROW EXECUTE FUNCTION immutable_runtime_trace();

CREATE OR REPLACE FUNCTION guard_runtime_run() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP IN ('UPDATE','DELETE') AND OLD.status<>'running' THEN
    RAISE EXCEPTION 'Final run records are immutable' USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'Run history cannot be deleted' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.agent_id,NEW.version_number,NEW.caller_id,
    NEW.model_id,NEW.config_hash,NEW.workflow_version,NEW.mode,NEW.started_at,
    NEW.channel,NEW.evaluation_id) IS DISTINCT FROM ROW(OLD.id,OLD.agent_id,
    OLD.version_number,OLD.caller_id,OLD.model_id,OLD.config_hash,OLD.workflow_version,
    OLD.mode,OLD.started_at,OLD.channel,OLD.evaluation_id) THEN
    RAISE EXCEPTION 'Immutable run identity' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'running' OR NOT EXISTS(SELECT 1 FROM agent_versions v
      WHERE v.agent_id=NEW.agent_id AND v.number=NEW.version_number AND v.status='snapshot'
        AND v.model_id=NEW.model_id AND v.config_hash=NEW.config_hash) THEN
      RAISE EXCEPTION 'Exact snapshot required' USING ERRCODE='23514';
    END IF;
    IF NEW.channel='evaluation' THEN
      IF NEW.caller_id NOT IN ('evaluation-customer-a','evaluation-customer-b','evaluation-no-permission')
        OR NOT EXISTS(SELECT 1 FROM evaluation_runs e WHERE e.id=NEW.evaluation_id
          AND e.status='running' AND e.agent_id=NEW.agent_id AND e.version_number=NEW.version_number
          AND e.config_hash=NEW.config_hash AND e.mode=NEW.mode) THEN
        RAISE EXCEPTION 'Trusted evaluation context required' USING ERRCODE='23514';
      END IF;
    ELSE
      IF NOT EXISTS(SELECT 1 FROM agent_invocations g WHERE g.agent_id=NEW.agent_id
        AND g.version_number=NEW.version_number AND g.user_id=NEW.caller_id AND g.enabled) THEN
        RAISE EXCEPTION 'Invocation grant required' USING ERRCODE='23514';
      END IF;
      IF NEW.channel='published' AND NOT EXISTS(SELECT 1 FROM agent_publications p
        JOIN version_governance g ON g.agent_id=p.agent_id AND g.version_number=p.version_number
        JOIN approvals a ON a.id=g.approval_id JOIN evaluation_runs e ON e.id=g.latest_evaluation_id
        WHERE p.agent_id=NEW.agent_id AND p.version_number=NEW.version_number AND p.enabled
          AND g.stage='published' AND g.config_hash=NEW.config_hash AND a.status='approved'
          AND a.evaluation_id=e.id AND a.config_hash=NEW.config_hash
          AND e.status='passed' AND e.mode=NEW.mode AND e.config_hash=NEW.config_hash) THEN
        RAISE EXCEPTION 'Published run requires an active approved release' USING ERRCODE='23514';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;

"""
